query IOT {
IOT {
  device_stats {
    entries(limit: 10, order_by: [{ classifications: ASC, classification_uuid: ASC, category: ASC }], filter_by: { classifications: { in: ["example"] }, classification_uuid: { in: ["example"] }, category: { in: ["Social Networking"] } }) {
      classifications
      classification_uuid
      category
      total
    }
    devices_count
    user_devices_count
    iot_devices_count
    server_devices_count
    un_classified_devices_count
  }
}
}
